const timestamp = Date.now();
request.variables.set('requestTimestamp', timestamp);
console.log('Running request at:', new Date(timestamp).toISOString());

requests.testScript:
// Basic response validation
tests['Status code is 200'] = response.status === 200;
tests['Response is JSON'] = response.headers['content-type'].includes('application/json');

// Schema validation
const userSchema = {
  type: 'object',
  required: ['id', 'name', 'email'],
  properties: {
    id: { type: 'string' },
    name: { type: 'string' },
    email: { type: 'string' }
  }
};

tests['Response matches user schema'] = jsonSchema.validate(response.body, userSchema);

// Performance testing
tests['Response time is acceptable'] = response.duration < 1000;

// Store user ID for next requests
environment.set('userId', response.body.id);

requests.preRequestScript:
// Ensure we have a user ID from previous request
if (!environment.get('userId')) {
  console.warn('No userId found in environment, using placeholder');
  environment.set('userId', 'placeholder-user-id');
}

// Get timestamp from variables or create new one
const timestamp = request.variables.get('requestTimestamp') || Date.now();
request.variables.set('requestTimestamp', timestamp);

requests.testScript:
// Verify item creation
tests['Status code is 201'] = response.status === 201;
tests['Item has an ID'] = response.body.id !== undefined;
tests['Item has the correct name'] = response.body.name === 'Test Item';

// Store item ID for next requests
environment.set('itemId', response.body.id);

// Verify item retrieval
tests['Status code is 200'] = response.status === 200;
tests['Item ID matches'] = response.body.id === environment.get('itemId');
tests['Item belongs to correct user'] = response.body.userId === environment.get('userId');

// Verify item deletion
tests['Status code is 204'] = response.status === 204;

// Clear item ID from environment
environment.unset('itemId');
